const e=[{id:"definition-quality-v294-prodromal-radyasyon-belirtileri",term:"Prodromal radyasyon belirtileri",aliases:["Prodromal radyasyon belirtileri","prodromal radyasyon bulguları","prodromal ARS belirtileri"],category:"Radyasyon biyofiziği / akut radyasyon sendromu",shortDefinition:"Akut radyasyon sendromunda maruziyetten saatler içinde gelişebilen bulantı, kusma, baş ağrısı, halsizlik ve ishal gibi erken uyarı bulgularıdır.",preAnswerSafeDefinition:"Radyasyon maruziyeti sonrası erken dönemde ortaya çıkan sistemik yakınmaları ifade eder; şiddeti maruziyet dozu ve süreyle ilişkilidir.",postAnswerExplanation:"Prodromal fazdaki kusmanın başlama zamanı ve semptom şiddeti alınan radyasyon dozu hakkında ipucu verir; ardından latent dönem ve hematopoetik, gastrointestinal veya nörovasküler sendrom bulguları gelişebilir.",tusPearl:"Radyasyon sonrası erken kusma ve gastrointestinal yakınmalar yüksek doz maruziyeti düşündürür; faz bilgisi akut radyasyon sendromu sorularında ayırt ettiricidir.",differentialPoint:"Prodromal belirtiler nonspesifiktir; tanısal değer maruziyet öyküsü, zamanlama ve lenfosit düşüşüyle birlikte değerlendirilince artar.",clinicalContext:"Radyasyon kazası, nükleer olay veya yüksek doz medikal/işlemsel maruziyet şüphesinde erken risk sınıflaması için kullanılır.",safeNestedTerms:["Akut radyasyon sendromu","Radyasyon maruziyeti","Lenfosit düşüşü"],canonicalTerm:"Prodromal radyasyon belirtileri",displayTerm:"Prodromal radyasyon belirtileri",normalizedAliases:[],postAnswerExpandedExplanation:"Prodromal fazdaki kusmanın başlama zamanı ve semptom şiddeti alınan radyasyon dozu hakkında ipucu verir; ardından latent dönem ve hematopoetik, gastrointestinal veya nörovasküler sendrom bulguları gelişebilir.",relatedTerms:["Akut radyasyon sendromu","Radyasyon maruziyeti","Lenfosit düşüşü"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!0,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!1,contextRequired:!1,phraseOnly:!0,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-subdiyafragmatik-serbest-hava",term:"Subdiyafragmatik serbest hava",aliases:["Subdiyafragmatik serbest hava","diyafram altında serbest hava","pnömoperitoneum bulgusu"],category:"Görüntüleme bulgusu / genel cerrahi",shortDefinition:"Direkt grafi veya görüntülemede diyafram altında görülen serbest gaz görünümüdür ve çoğunlukla içi boş organ perforasyonunu düşündürür.",preAnswerSafeDefinition:"Karın içinde serbest gaz varlığını gösteren radyolojik bir bulgudur; klinik bağlamla birlikte yorumlanır.",postAnswerExplanation:"Periton boşluğuna hava geçişi en sık gastrointestinal perforasyonla ilişkilidir; ani karın ağrısı, defans/rebound ve sepsis bulguları varsa acil cerrahi değerlendirme gerekir.",tusPearl:"Akut batında diyafram altı serbest hava, perforasyon düşünülmesi gereken yüksek değerli görüntüleme ipucudur.",differentialPoint:"Postoperatif erken dönemde sınırlı serbest hava beklenebilir; klinik kötüleşme veya peritoneal irritasyon perforasyon lehinedir.",clinicalContext:"Akut batın, peptik ülser perforasyonu, barsak perforasyonu ve travma değerlendirmesinde önemlidir.",safeNestedTerms:["Pnömoperitoneum","Perforasyon","Defans","Rebound"],canonicalTerm:"Subdiyafragmatik serbest hava",displayTerm:"Subdiyafragmatik serbest hava",normalizedAliases:[],postAnswerExpandedExplanation:"Periton boşluğuna hava geçişi en sık gastrointestinal perforasyonla ilişkilidir; ani karın ağrısı, defans/rebound ve sepsis bulguları varsa acil cerrahi değerlendirme gerekir.",relatedTerms:["Pnömoperitoneum","Perforasyon","Defans","Rebound"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!0,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!1,contextRequired:!1,phraseOnly:!0,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-nonkontrast-kraniyal-bt",term:"Nonkontrast kraniyal BT",aliases:["Nonkontrast kraniyal BT","kontrastsız beyin BT","kontrastsız kraniyal tomografi"],category:"Görüntüleme tetkiki / nöroloji",shortDefinition:"Kontrast madde verilmeden çekilen beyin BT incelemesidir; akut kanama, kitle etkisi ve erken iskemik değişikliklerin değerlendirilmesinde kullanılır.",preAnswerSafeDefinition:"Akut nörolojik tabloda intrakraniyal kanama veya belirgin yapısal lezyon varlığını hızlı değerlendiren görüntüleme yöntemidir.",postAnswerExplanation:"İskemik inmede trombolitik tedavi düşünülmeden önce intrakraniyal kanamanın dışlanması gerekir; nonkontrast BT bu nedenle acil yaklaşımda temel basamaktır.",tusPearl:"Akut inme şüphesinde tedavi kararından önce kanamayı dışlamak için nonkontrast kraniyal BT istenir.",differentialPoint:"MR difüzyon akut iskemiyi daha duyarlı gösterebilir; BT ise acilde kanama dışlama ve hızlı erişilebilirlik açısından öne çıkar.",clinicalContext:"Akut inme, travma, ani baş ağrısı ve bilinç değişikliği değerlendirmesinde kullanılır.",safeNestedTerms:["Akut inme","İntrakraniyal kanama","MR difüzyon kısıtlılığı","Tromboliz"],canonicalTerm:"Nonkontrast kraniyal BT",displayTerm:"Nonkontrast kraniyal BT",normalizedAliases:[],postAnswerExpandedExplanation:"İskemik inmede trombolitik tedavi düşünülmeden önce intrakraniyal kanamanın dışlanması gerekir; nonkontrast BT bu nedenle acil yaklaşımda temel basamaktır.",relatedTerms:["Akut inme","İntrakraniyal kanama","MR difüzyon kısıtlılığı","Tromboliz"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!0,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!1,contextRequired:!1,phraseOnly:!0,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-anatomik-enfiye-cukuru",term:"Anatomik enfiye çukuru",aliases:["Anatomik enfiye çukuru","anatomical snuffbox","enfiye çukuru"],category:"Anatomik lokalizasyon / ortopedi",shortDefinition:"Başparmak ekstansiyonu ile belirginleşen, skafoid kemiğin palpe edildiği radial el bileği çukurudur.",preAnswerSafeDefinition:"El bileği radial tarafında yer alan ve travma sonrası palpasyonla değerlendirilen anatomik bir bölgedir.",postAnswerExplanation:"FOOSH tipi düşme sonrası anatomik enfiye çukuru hassasiyeti skafoid kırığı açısından uyarıcıdır; erken grafi normal olsa bile klinik şüphede immobilizasyon ve kontrol görüntüleme gerekir.",tusPearl:"El bileği travması + anatomik enfiye çukuru hassasiyeti skafoid kırığını düşündürür.",differentialPoint:"De Quervain tenosinoviti radial stiloid çevresinde ağrı yapabilir; travma öyküsü ve skafoid palpasyon hassasiyeti kırık lehinedir.",clinicalContext:"El bileği travması, skafoid kırığı ve radial taraf ağrısı değerlendirmesinde kullanılır.",safeNestedTerms:["Skafoid kırığı","FOOSH","Radial el bileği"],canonicalTerm:"Anatomik enfiye çukuru",displayTerm:"Anatomik enfiye çukuru",normalizedAliases:[],postAnswerExpandedExplanation:"FOOSH tipi düşme sonrası anatomik enfiye çukuru hassasiyeti skafoid kırığı açısından uyarıcıdır; erken grafi normal olsa bile klinik şüphede immobilizasyon ve kontrol görüntüleme gerekir.",relatedTerms:["Skafoid kırığı","FOOSH","Radial el bileği"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!0,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!1,contextRequired:!1,phraseOnly:!0,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-rebound",term:"Rebound",aliases:["Rebound","rebound hassasiyet","rebound tenderness"],category:"Fizik muayene bulgusu / akut batın",shortDefinition:"Karın palpasyonunda bası kaldırıldığında ağrının artmasıdır; peritoneal irritasyonu düşündüren muayene bulgusudur.",preAnswerSafeDefinition:"Karın muayenesinde periton duyarlılığını değerlendiren bir hassasiyet bulgusudur.",postAnswerExplanation:"İnflame veya irritasyon altındaki periton ani gerilmeye duyarlı hale gelir; rebound, defans ve rijidite ile birlikte akut batında cerrahi patoloji olasılığını artırır.",tusPearl:"Akut karın ağrısında rebound ve defans peritoneal irritasyon bulgusu olarak cerrahi aciliyet açısından önemlidir.",differentialPoint:"Yüzeyel palpasyon hassasiyeti nonspesifik olabilir; rebound basının kaldırılmasıyla artan ağrıyı ifade eder.",clinicalContext:"Apandisit, perforasyon, peritonit ve akut batın değerlendirmesinde kullanılır.",safeNestedTerms:["Defans","Peritoneal irritasyon bulgusu","Akut batın","Peritonit"],canonicalTerm:"Rebound",displayTerm:"Rebound",normalizedAliases:[],postAnswerExpandedExplanation:"İnflame veya irritasyon altındaki periton ani gerilmeye duyarlı hale gelir; rebound, defans ve rijidite ile birlikte akut batında cerrahi patoloji olasılığını artırır.",relatedTerms:["Defans","Peritoneal irritasyon bulgusu","Akut batın","Peritonit"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!1,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!0,contextRequired:!1,phraseOnly:!1,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-sentinel-lenf-nodu-biyopsisi",term:"Sentinel lenf nodu biyopsisi",aliases:["Sentinel lenf nodu biyopsisi","sentinel nod biyopsisi","SLNB"],category:"Cerrahi / onkolojik evreleme",shortDefinition:"Primer tümörden lenfatik drenajı alan ilk lenf nodunun işaretlenip örneklenmesi işlemidir.",preAnswerSafeDefinition:"Tümörün bölgesel lenfatik yayılımını daha sınırlı cerrahi örnekleme ile değerlendiren onkolojik evreleme işlemidir.",postAnswerExplanation:"Sentinel nod negatifse geniş lenf nodu diseksiyonundan kaçınılabilir; pozitiflik nodal evreleme ve adjuvan tedavi planını etkiler. Meme kanseri ve melanomda sık kullanılır.",tusPearl:"Meme kanseri ve melanomda sentinel nod biyopsisi nodal evreleme için aksiller/lenf nodu diseksiyonuna göre daha sınırlı yaklaşımdır.",differentialPoint:"Sentinel nod biyopsisi tanısal evreleme işlemidir; terapötik geniş nod diseksiyonu değildir.",clinicalContext:"Meme kanseri, melanom ve seçilmiş solid tümörlerde bölgesel nodal evreleme için kullanılır.",safeNestedTerms:["Sentinel lenf nodu","Lenfatik drenaj","Nodal evreleme","Aksiller diseksiyon"],canonicalTerm:"Sentinel lenf nodu biyopsisi",displayTerm:"Sentinel lenf nodu biyopsisi",normalizedAliases:[],postAnswerExpandedExplanation:"Sentinel nod negatifse geniş lenf nodu diseksiyonundan kaçınılabilir; pozitiflik nodal evreleme ve adjuvan tedavi planını etkiler. Meme kanseri ve melanomda sık kullanılır.",relatedTerms:["Sentinel lenf nodu","Lenfatik drenaj","Nodal evreleme","Aksiller diseksiyon"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!0,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!1,contextRequired:!1,phraseOnly:!0,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-ilk-basamak-tedavi",term:"İlk basamak tedavi",aliases:["İlk basamak tedavi","ilk tedavi basamağı","öncelikli tedavi yaklaşımı"],category:"TUS karar terimi / klinik yönetim",shortDefinition:"Bir klinik durumda ilk uygulanması gereken tedavi veya stabilizasyon adımını ifade eder.",preAnswerSafeDefinition:"Tedavi sıralamasında önceliklendirme gerektiren klinik karar kavramıdır; ayrıntılı seçenek bilgisi cevap sonrası değerlendirilmelidir.",postAnswerExplanation:"TUS sorularında “ilk basamak” çoğu zaman definitif tedaviden önce yaşamı tehdit eden sorunu stabilize etmeyi hedefler; tedavi sırası tanı kadar önemlidir.",tusPearl:"“İlk” sorularında stabilizasyon, güvenlik ve zaman kritik müdahale definitif tedaviden ayrılmalıdır.",differentialPoint:"Definitif tedavi hastalığı ortadan kaldırmayı; ilk basamak tedavi acil riski azaltmayı veya tanı/tedavi sürecini başlatmayı hedefleyebilir.",clinicalContext:"Acil, yoğun bakım, enfeksiyon, obstetri ve elektrolit bozukluğu sorularında tedavi sırası belirlemede önemlidir.",safeNestedTerms:["Stabilizasyon","Definitif tedavi","Acil tedavi yaklaşımı","Hemodinamik instabilite"],canonicalTerm:"İlk basamak tedavi",displayTerm:"İlk basamak tedavi",normalizedAliases:[],postAnswerExpandedExplanation:"TUS sorularında “ilk basamak” çoğu zaman definitif tedaviden önce yaşamı tehdit eden sorunu stabilize etmeyi hedefler; tedavi sırası tanı kadar önemlidir.",relatedTerms:["Stabilizasyon","Definitif tedavi","Acil tedavi yaklaşımı","Hemodinamik instabilite"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!0,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!1,contextRequired:!1,phraseOnly:!0,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-agir-ozellikli-preeklampsi",term:"Ağır özellikli preeklampsi",aliases:["Ağır özellikli preeklampsi","şiddetli preeklampsi","severe preeclampsia"],category:"Kadın doğum / hipertansif gebelik hastalığı",shortDefinition:"Preeklampsiye ağır hipertansiyon, trombositopeni, böbrek/karaciğer etkilenimi, pulmoner ödem veya nörolojik bulguların eşlik ettiği tablodur.",preAnswerSafeDefinition:"Gebelikte hipertansif hastalık spektrumunda organ etkilenimi ve maternal-fetal risk artışıyla ilişkili ağır klinik formdur.",postAnswerExplanation:"Ağır özellikler maternal nöbet, inme, HELLP sendromu ve fetal komplikasyon riskini artırır; magnezyum sülfatla nöbet profilaksisi ve gebelik haftasına göre doğum planı değerlendirilir.",tusPearl:"Şiddetli baş ağrısı, görme bozukluğu, epigastrik ağrı, trombosit düşüklüğü veya pulmoner ödem ağır özellik lehinedir.",differentialPoint:"Eklampsi nöbet varlığıyla preeklampsiden ayrılır; HELLP hemoliz, karaciğer enzim yüksekliği ve trombositopeni ile öne çıkar.",clinicalContext:"Gebelik veya postpartum dönemde hipertansiyon ve organ disfonksiyonu bulgularıyla değerlendirilir.",safeNestedTerms:["Preeklampsi","Eklampsi","HELLP sendromu","Magnezyum sülfat","Trombositopeni"],canonicalTerm:"Ağır özellikli preeklampsi",displayTerm:"Ağır özellikli preeklampsi",normalizedAliases:[],postAnswerExpandedExplanation:"Ağır özellikler maternal nöbet, inme, HELLP sendromu ve fetal komplikasyon riskini artırır; magnezyum sülfatla nöbet profilaksisi ve gebelik haftasına göre doğum planı değerlendirilir.",relatedTerms:["Preeklampsi","Eklampsi","HELLP sendromu","Magnezyum sülfat","Trombositopeni"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!0,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!1,contextRequired:!1,phraseOnly:!0,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-sentinel-lenf-nodu",term:"Sentinel lenf nodu",aliases:["Sentinel lenf nodu","sentinel nod","sentinel lymph node"],category:"Anatomi / onkolojik evreleme",shortDefinition:"Primer tümör bölgesinden lenfatik drenajın ilk ulaştığı lenf nodudur.",preAnswerSafeDefinition:"Tümörün lenfatik yayılım yolunda ilk değerlendirilmesi hedeflenen bölgesel lenf nodunu ifade eder.",postAnswerExplanation:"Sentinel lenf nodu pozitifliği bölgesel metastaz olasılığını ve evrelemeyi etkiler; negatiflik bazı hastalarda geniş nod diseksiyonundan kaçınmayı sağlar.",tusPearl:"Meme kanseri ve melanomda sentinel nod kavramı nodal evreleme ve cerrahi morbiditeyi azaltma açısından önemlidir.",differentialPoint:"Sentinel nod anatomik drenajdaki ilk noddur; klinik olarak büyümüş herhangi bir lenf nodu sentinel nod anlamına gelmez.",clinicalContext:"Meme kanseri, melanom ve seçilmiş tümörlerde lenfatik yayılım değerlendirmesinde kullanılır.",safeNestedTerms:["Sentinel lenf nodu biyopsisi","Lenfatik drenaj","Nodal evreleme"],canonicalTerm:"Sentinel lenf nodu",displayTerm:"Sentinel lenf nodu",normalizedAliases:[],postAnswerExpandedExplanation:"Sentinel lenf nodu pozitifliği bölgesel metastaz olasılığını ve evrelemeyi etkiler; negatiflik bazı hastalarda geniş nod diseksiyonundan kaçınmayı sağlar.",relatedTerms:["Sentinel lenf nodu biyopsisi","Lenfatik drenaj","Nodal evreleme"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!0,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!1,contextRequired:!1,phraseOnly:!0,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-hava-yolu-odemi",term:"Hava yolu ödemi",aliases:["Hava yolu ödemi","airway edema","hava yolu şişliği"],category:"Acil / hava yolu patolojisi",shortDefinition:"Üst veya alt hava yolunda mukozal şişlik gelişerek hava akımını kısıtlayabilen klinik durumdur.",preAnswerSafeDefinition:"Solunum yolunda şişlik ve hava akımı kısıtlanması riskiyle ilişkili acil değerlendirme gerektiren bulgudur.",postAnswerExplanation:"Anafilaksi, inhalasyon hasarı veya enfeksiyonlarda gelişebilir; ses kısıklığı, stridor, dil/dudak şişliği veya hipoksemi hava yolu güvenliğini öncelikli hale getirir.",tusPearl:"Stridor, ses kısıklığı veya hızlı ilerleyen mukozal ödem hava yolu güvenliği açısından kırmızı bayraktır.",differentialPoint:"Bronkospazm alt hava yolu düz kas daralmasıdır; laringeal/hava yolu ödemi üst hava yolu obstrüksiyonu ve stridorla öne çıkabilir.",clinicalContext:"Anafilaksi, epiglotit, inhalasyon hasarı ve anjiyoödem değerlendirmesinde önemlidir.",safeNestedTerms:["Laringeal ödem","Stridor","Bronkospazm","Anafilaksi","Hava yolu obstrüksiyonu"],canonicalTerm:"Hava yolu ödemi",displayTerm:"Hava yolu ödemi",normalizedAliases:[],postAnswerExpandedExplanation:"Anafilaksi, inhalasyon hasarı veya enfeksiyonlarda gelişebilir; ses kısıklığı, stridor, dil/dudak şişliği veya hipoksemi hava yolu güvenliğini öncelikli hale getirir.",relatedTerms:["Laringeal ödem","Stridor","Bronkospazm","Anafilaksi","Hava yolu obstrüksiyonu"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!0,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!1,contextRequired:!1,phraseOnly:!0,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-insulin-glukoz-tedavisi",term:"İnsülin-glukoz tedavisi",aliases:["İnsülin-glukoz tedavisi","insülin dekstroz tedavisi","insülin-glukoz infüzyonu"],category:"Acil / elektrolit tedavisi",shortDefinition:"İnsülinin potasyumu hücre içine kaydırıcı etkisinden yararlanmak için glukozla birlikte verilen geçici hiperkalemi tedavisidir.",preAnswerSafeDefinition:"Elektrolit acillerinde hücre içi-dışı iyon dağılımını geçici olarak değiştirmeye yönelik tedavi yaklaşımıdır.",postAnswerExplanation:"İnsülin Na/K-ATPaz aktivitesini artırarak serum potasyumunu düşürür; glukoz hipoglisemiyi önlemek için verilir. EKG değişikliği varsa membran stabilizasyonu önceliklidir.",tusPearl:"Hiperkalemide insülin-glukoz potasyumu hücre içine kaydırır; EKG değişikliğinde önce kalsiyumla membran stabilizasyonu düşünülür.",differentialPoint:"Kalsiyum glukonat potasyumu düşürmez, kardiyak membranı stabilize eder; insülin-glukoz serum potasyumunu geçici azaltır.",clinicalContext:"Acil hiperkalemi tedavisinde, özellikle böbrek yetmezliği veya ilaç ilişkili potasyum yüksekliğinde kullanılır.",safeNestedTerms:["Hiperkalemi","Na/K-ATPaz","Membran stabilizasyonu","Kalsiyum glukonat","Hipoglisemi"],canonicalTerm:"İnsülin-glukoz tedavisi",displayTerm:"İnsülin-glukoz tedavisi",normalizedAliases:[],postAnswerExpandedExplanation:"İnsülin Na/K-ATPaz aktivitesini artırarak serum potasyumunu düşürür; glukoz hipoglisemiyi önlemek için verilir. EKG değişikliği varsa membran stabilizasyonu önceliklidir.",relatedTerms:["Hiperkalemi","Na/K-ATPaz","Membran stabilizasyonu","Kalsiyum glukonat","Hipoglisemi"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!0,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!1,contextRequired:!1,phraseOnly:!0,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-tansiyon-pnomotoraks",term:"Tansiyon pnömotoraks",aliases:["Tansiyon pnömotoraks","tension pneumothorax","basınçlı pnömotoraks"],category:"Acil / pulmonoloji",shortDefinition:"Plevral boşlukta basınçlı hava birikimiyle venöz dönüşü azaltıp mediastinal kayma ve obstrüktif şok oluşturabilen acil tablodur.",preAnswerSafeDefinition:"Plevral basınç artışı ve dolaşım-solunum bozulması riski taşıyan yaşamı tehdit eden toraks acilidir.",postAnswerExplanation:"Tek yönlü hava kaçağı intratorasik basıncı artırır; hipotansiyon, juguler ven dolgunluğu, solunum sıkıntısı ve trakeal deviasyon görülebilir. Klinik şüphede görüntüleme beklenmeden dekompresyon gerekir.",tusPearl:"Tansiyon pnömotoraks klinik tanıdır; hemodinamik bozulma varsa acil iğne dekompresyonu/tüp torakostomi düşünülür.",differentialPoint:"Basit pnömotoraksta basınç etkisi ve obstrüktif şok beklenmeyebilir; tansiyon pnömotoraks dolaşımı bozar.",clinicalContext:"Travma, mekanik ventilasyon veya spontan pnömotoraks sonrası akut solunum-dolaşım bozukluğunda düşünülür.",safeNestedTerms:["Plevral boşluk","Obstrüktif şok","İğne dekompresyonu","Tüp torakostomi","Mediastinal kayma"],canonicalTerm:"Tansiyon pnömotoraks",displayTerm:"Tansiyon pnömotoraks",normalizedAliases:[],postAnswerExpandedExplanation:"Tek yönlü hava kaçağı intratorasik basıncı artırır; hipotansiyon, juguler ven dolgunluğu, solunum sıkıntısı ve trakeal deviasyon görülebilir. Klinik şüphede görüntüleme beklenmeden dekompresyon gerekir.",relatedTerms:["Plevral boşluk","Obstrüktif şok","İğne dekompresyonu","Tüp torakostomi","Mediastinal kayma"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!0,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!1,contextRequired:!1,phraseOnly:!0,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-igne-dekompresyonu",term:"İğne dekompresyonu",aliases:["İğne dekompresyonu","needle decompression","torasik iğne dekompresyonu"],category:"Acil girişim / toraks",shortDefinition:"Tansiyon pnömotoraksta plevral basıncı hızla azaltmak için göğüs duvarından iğne veya kateterle hava boşaltma girişimidir.",preAnswerSafeDefinition:"Plevral basınç artışına bağlı akut solunum-dolaşım bozukluğunu geçici olarak rahatlatmaya yönelik acil girişimdir.",postAnswerExplanation:"İğne dekompresyonu hızlı rahatlama sağlar ancak kalıcı tedavi genellikle tüp torakostomidir; klinik şüphe kuvvetliyse görüntüleme beklenmeyebilir.",tusPearl:"Tansiyon pnömotoraks şüphesinde hemodinamik bozulma varsa görüntüleme beklemeden dekompresyon önceliklidir.",differentialPoint:"İğne dekompresyonu geçici acil rahatlatma; tüp torakostomi kalıcı drenaj sağlar.",clinicalContext:"Tansiyon pnömotoraks, travma ve mekanik ventilasyon ilişkili akut göğüs acillerinde kullanılır.",safeNestedTerms:["Tansiyon pnömotoraks","Tüp torakostomi","Plevral basınç"],canonicalTerm:"İğne dekompresyonu",displayTerm:"İğne dekompresyonu",normalizedAliases:[],postAnswerExpandedExplanation:"İğne dekompresyonu hızlı rahatlama sağlar ancak kalıcı tedavi genellikle tüp torakostomidir; klinik şüphe kuvvetliyse görüntüleme beklenmeyebilir.",relatedTerms:["Tansiyon pnömotoraks","Tüp torakostomi","Plevral basınç"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!0,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!1,contextRequired:!1,phraseOnly:!0,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-status-epileptikus",term:"Status epileptikus",aliases:["Status epileptikus","status epilepticus","uzamış nöbet"],category:"Nöroloji / acil",shortDefinition:"Uzamış nöbet aktivitesi veya bilinç tam düzelmeden tekrarlayan nöbetlerle karakterize nörolojik acildir.",preAnswerSafeDefinition:"Süresi ve tekrarlama paterni nedeniyle hızlı nörolojik değerlendirme ve tedavi gerektiren nöbet tablosudur.",postAnswerExplanation:"Uzayan nöbet nöronal hasar, hipoksi, aspirasyon ve metabolik bozulma riskini artırır; hızlı benzodiazepin tedavisi ve altta yatan nedenin düzeltilmesi esastır.",tusPearl:"Status epileptikusta hızlı nöbet kontrolü için ilk basamak benzodiazepindir; kalıcı kontrol için ikinci basamak antiepileptik eklenir.",differentialPoint:"Tek kısa nöbetten farklı olarak status epileptikus süreklilik/tekrarlama nedeniyle acil tedavi gerektirir.",clinicalContext:"Acil nöroloji, toksikoloji, metabolik bozukluklar ve epilepsi yönetiminde önemlidir.",safeNestedTerms:["Benzodiazepin","Antiepileptik tedavi","Hipoksi","Aspirasyon"],canonicalTerm:"Status epileptikus",displayTerm:"Status epileptikus",normalizedAliases:[],postAnswerExpandedExplanation:"Uzayan nöbet nöronal hasar, hipoksi, aspirasyon ve metabolik bozulma riskini artırır; hızlı benzodiazepin tedavisi ve altta yatan nedenin düzeltilmesi esastır.",relatedTerms:["Benzodiazepin","Antiepileptik tedavi","Hipoksi","Aspirasyon"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!0,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!1,contextRequired:!1,phraseOnly:!0,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-malign-hipertermi",term:"Malign hipertermi",aliases:["Malign hipertermi","malignant hyperthermia"],category:"Anestezi / farmakogenetik acil",shortDefinition:"Genetik yatkın bireylerde volatil anestezikler veya suksinilkolin sonrası gelişen hipermetabolik kas krizidir.",preAnswerSafeDefinition:"Anestezi ilişkili tetikleyicilerle ortaya çıkabilen, kas metabolizması ve ısı üretimi bozukluğu içeren acil tablodur.",postAnswerExplanation:"RYR1 ilişkili kalsiyum salınım artışı kas rijiditesi, hiperkarbi, asidoz, hiperkalemi ve hipertermiye yol açar; tedavide dantrolen kullanılır.",tusPearl:"Volatil anestezik/suksinilkolin sonrası kas rijiditesi + hipertermi + asidoz/hiperkalemi malign hipertermi lehinedir; dantrolen verilir.",differentialPoint:"Nöroleptik malign sendrom dopamin blokajı ve daha yavaş seyirle; malign hipertermi anestezi tetikleyicisiyle ilişkilidir.",clinicalContext:"Ameliyathane ve perioperatif acil yönetimde hayati önem taşır.",safeNestedTerms:["Suksinilkolin","Dantrolen","RYR1","Hiperkalemi","Metabolik asidoz"],canonicalTerm:"Malign hipertermi",displayTerm:"Malign hipertermi",normalizedAliases:[],postAnswerExpandedExplanation:"RYR1 ilişkili kalsiyum salınım artışı kas rijiditesi, hiperkarbi, asidoz, hiperkalemi ve hipertermiye yol açar; tedavide dantrolen kullanılır.",relatedTerms:["Suksinilkolin","Dantrolen","RYR1","Hiperkalemi","Metabolik asidoz"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!0,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!1,contextRequired:!1,phraseOnly:!0,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-mcroberts-manevrasi",term:"McRoberts manevrası",aliases:["McRoberts manevrası","Roberts manevrası","McRoberts maneuver"],category:"Obstetrik manevra / omuz distosisi",shortDefinition:"Omuz distosisinde annenin kalçalarının aşırı fleksiyona getirilerek sakrum-pelvis açısının değiştirilmesini sağlayan manevradır.",preAnswerSafeDefinition:"Doğum sırasında omuzların takılmasıyla ilişkili mekanik obstetrik sorunda kullanılan noninvaziv pozisyon manevrasıdır.",postAnswerExplanation:"McRoberts manevrası sakral promontoryum açısını değiştirerek anterior omuzun kurtulmasına yardımcı olur; sıklıkla suprapubik bası ile birlikte uygulanır.",tusPearl:"Omuz distosisinde fundal bası yapılmaz; McRoberts manevrası ve suprapubik bası ilk güvenli yaklaşımlar arasındadır.",differentialPoint:"Suprapubik bası fetal omzu döndürmeye yardım eder; fundal bası impaksiyonu artırabileceği için önerilmez.",clinicalContext:"Turtle sign ve fetal baş çıktıktan sonra omuzların doğurtulamaması durumunda kullanılır.",safeNestedTerms:["Omuz distosisi","Suprapubik bası","Turtle sign","Fundal bası"],canonicalTerm:"McRoberts manevrası",displayTerm:"McRoberts manevrası",normalizedAliases:[],postAnswerExpandedExplanation:"McRoberts manevrası sakral promontoryum açısını değiştirerek anterior omuzun kurtulmasına yardımcı olur; sıklıkla suprapubik bası ile birlikte uygulanır.",relatedTerms:["Omuz distosisi","Suprapubik bası","Turtle sign","Fundal bası"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!0,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!1,contextRequired:!1,phraseOnly:!0,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-reynolds-pentadi",term:"Reynolds pentadı",aliases:["Reynolds pentadı","Reynolds pentad"],category:"Gastroenteroloji / ağır kolanjit bulgusu",shortDefinition:"Charcot triadına hipotansiyon ve mental durum değişikliğinin eklenmesiyle tanımlanan ağır akut kolanjit bulgu setidir.",preAnswerSafeDefinition:"Safra yolu enfeksiyonunda sistemik dolaşım ve bilinç etkilenimini de içeren ağır klinik bulgu kombinasyonudur.",postAnswerExplanation:"Ateş, sarılık ve sağ üst kadran ağrısına hipotansiyon ve konfüzyon eklenmesi sepsis/ağır kolanjit riskini gösterir; antibiyotik ve biliyer drenaj gecikmemelidir.",tusPearl:"Charcot triadı kolanjiti; Reynolds pentadı ağır/septik kolanjiti düşündürür.",differentialPoint:"Charcot triadı üç bulgudan oluşur; Reynolds pentadı sistemik şok ve mental durum değişikliği eklenmiş ağır formdur.",clinicalContext:"Koledok taşı veya safra yolu obstrüksiyonu zemininde akut kolanjit değerlendirmesinde kullanılır.",safeNestedTerms:["Charcot triadı","Akut kolanjit","Safra yolu obstrüksiyonu","Sepsis","Biliyer drenaj"],canonicalTerm:"Reynolds pentadı",displayTerm:"Reynolds pentadı",normalizedAliases:[],postAnswerExpandedExplanation:"Ateş, sarılık ve sağ üst kadran ağrısına hipotansiyon ve konfüzyon eklenmesi sepsis/ağır kolanjit riskini gösterir; antibiyotik ve biliyer drenaj gecikmemelidir.",relatedTerms:["Charcot triadı","Akut kolanjit","Safra yolu obstrüksiyonu","Sepsis","Biliyer drenaj"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!0,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!1,contextRequired:!1,phraseOnly:!0,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-ablatio-plasenta",term:"Ablatio plasenta",aliases:["Ablatio plasenta","plasenta dekolmanı","abruptio placentae"],category:"Kadın doğum / obstetrik kanama",shortDefinition:"Plasentanın doğumdan önce uterin duvardan erken ayrılmasıdır; ağrılı vajinal kanama, uterus hassasiyeti ve fetal distresle seyredebilir.",preAnswerSafeDefinition:"Gebeliğin geç döneminde plasentanın uterusa tutunmasıyla ilgili kanama ve fetal-maternal risk oluşturan obstetrik tablodur.",postAnswerExplanation:"Plasental ayrılma uteroplasental perfüzyonu bozar; hipertansiyon, travma ve kokain risk faktörleri arasındadır. Ağrılı kanama ve hassas/sert uterus tipiktir.",tusPearl:"Ağrılı vajinal kanama + uterus hassasiyeti/sertliği ablatio plasentayı; ağrısız kanama plasenta previayı düşündürür.",differentialPoint:"Plasenta previa genellikle ağrısız kanama yapar; ablatio plasenta ağrı, uterin hassasiyet ve fetal distresle öne çıkar.",clinicalContext:"Gebelikte üçüncü trimester kanama ve fetal distres değerlendirmesinde önemlidir.",safeNestedTerms:["Plasenta previa","Fetal distres","Uteroplasental perfüzyon","Hipertansiyon"],canonicalTerm:"Ablatio plasenta",displayTerm:"Ablatio plasenta",normalizedAliases:[],postAnswerExpandedExplanation:"Plasental ayrılma uteroplasental perfüzyonu bozar; hipertansiyon, travma ve kokain risk faktörleri arasındadır. Ağrılı kanama ve hassas/sert uterus tipiktir.",relatedTerms:["Plasenta previa","Fetal distres","Uteroplasental perfüzyon","Hipertansiyon"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!0,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!1,contextRequired:!1,phraseOnly:!0,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-ektopik-gebelik",term:"Ektopik gebelik",aliases:["Ektopik gebelik","dış gebelik","ectopic pregnancy"],category:"Kadın doğum / erken gebelik acili",shortDefinition:"Gebeliğin uterin kavite dışında, en sık fallop tüpünde yerleşmesidir.",preAnswerSafeDefinition:"Gebelik dokusunun normal uterin kavite dışında yerleşmesiyle ilişkili erken gebelik komplikasyonudur.",postAnswerExplanation:"Rüptür gelişirse intraabdominal kanama ve şok oluşturabilir. Amenore, alt karın ağrısı, vajinal kanama ve pozitif β-hCG bağlamında transvajinal USG ile değerlendirilir.",tusPearl:"Pozitif β-hCG + uterin kavitede gebelik görülmemesi + karın ağrısı/vajinal kanama ektopik gebelik açısından uyarıcıdır.",differentialPoint:"Spontan abortusta gebelik uterin kavite içindedir; ektopik gebelikte ekstrauterin yerleşim ve rüptür riski vardır.",clinicalContext:"Erken gebelikte karın ağrısı, vajinal kanama ve hemodinamik instabilite değerlendirmesinde önemlidir.",safeNestedTerms:["β-hCG","Transvajinal ultrasonografi","Rüptüre ektopik gebelik","Hemodinamik instabilite"],canonicalTerm:"Ektopik gebelik",displayTerm:"Ektopik gebelik",normalizedAliases:[],postAnswerExpandedExplanation:"Rüptür gelişirse intraabdominal kanama ve şok oluşturabilir. Amenore, alt karın ağrısı, vajinal kanama ve pozitif β-hCG bağlamında transvajinal USG ile değerlendirilir.",relatedTerms:["β-hCG","Transvajinal ultrasonografi","Rüptüre ektopik gebelik","Hemodinamik instabilite"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!0,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!1,contextRequired:!1,phraseOnly:!0,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-laringeal-odem",term:"Laringeal ödem",aliases:["Laringeal ödem","laryngeal edema","larinks ödemi"],category:"Acil / üst hava yolu",shortDefinition:"Larinks mukozasında şişlik gelişerek üst hava yolu darlığı, stridor ve solunum yetmezliği riski oluşturabilen durumdur.",preAnswerSafeDefinition:"Üst hava yolunda şişlik ve hava geçişinde daralma riskiyle ilişkili acil solunum bulgusudur.",postAnswerExplanation:"Anafilaksi, inhalasyon hasarı, enfeksiyon veya anjiyoödemle gelişebilir; ses kısıklığı ve stridor varsa erken hava yolu güvenliği planlanmalıdır.",tusPearl:"Stridor üst hava yolu darlığını gösterir; laringeal ödem şüphesinde hava yolu yönetimi önceliklidir.",differentialPoint:"Wheezing alt hava yolu daralmasını; stridor ve ses kısıklığı üst hava yolu problemini düşündürür.",clinicalContext:"Anafilaksi, epiglotit, anjiyoödem ve inhalasyon hasarı değerlendirmesinde kullanılır.",safeNestedTerms:["Stridor","Anafilaksi","Anjiyoödem","Hava yolu ödemi","Wheezing"],canonicalTerm:"Laringeal ödem",displayTerm:"Laringeal ödem",normalizedAliases:[],postAnswerExpandedExplanation:"Anafilaksi, inhalasyon hasarı, enfeksiyon veya anjiyoödemle gelişebilir; ses kısıklığı ve stridor varsa erken hava yolu güvenliği planlanmalıdır.",relatedTerms:["Stridor","Anafilaksi","Anjiyoödem","Hava yolu ödemi","Wheezing"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!0,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!1,contextRequired:!1,phraseOnly:!0,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-akut-kolanjit",term:"Akut kolanjit",aliases:["Akut kolanjit","ascending cholangitis","kolanjit"],category:"Gastroenteroloji / safra yolu enfeksiyonu",shortDefinition:"Safra yolu obstrüksiyonu zemininde gelişen, ateş, sarılık ve sağ üst kadran ağrısıyla seyredebilən bakteriyel safra yolu enfeksiyonudur.",preAnswerSafeDefinition:"Safra yollarında enfeksiyon ve akım bozukluğu ile ilişkili, sistemik bulgular oluşturabilen klinik tablodur.",postAnswerExplanation:"Obstrüksiyon bakteriyel çoğalmayı ve basıncı artırır; ağır olguda sepsis gelişebilir. Tedavide antibiyotik ve gerekirse ERCP ile biliyer drenaj gerekir.",tusPearl:"Charcot triadı ateş + sarılık + sağ üst kadran ağrısıdır; hipotansiyon/konfüzyon eklenirse Reynolds pentadı ağır kolanjiti gösterir.",differentialPoint:"Akut kolesistit safra kesesi inflamasyonudur; kolanjit safra yolları enfeksiyonu ve sarılık/sepsis riskiyle öne çıkar.",clinicalContext:"Koledok taşı, biliyer obstrüksiyon, ERCP sonrası ateş ve sarılık değerlendirmesinde önemlidir.",safeNestedTerms:["Charcot triadı","Reynolds pentadı","Safra yolu obstrüksiyonu","ERCP","Biliyer drenaj"],canonicalTerm:"Akut kolanjit",displayTerm:"Akut kolanjit",normalizedAliases:[],postAnswerExpandedExplanation:"Obstrüksiyon bakteriyel çoğalmayı ve basıncı artırır; ağır olguda sepsis gelişebilir. Tedavide antibiyotik ve gerekirse ERCP ile biliyer drenaj gerekir.",relatedTerms:["Charcot triadı","Reynolds pentadı","Safra yolu obstrüksiyonu","ERCP","Biliyer drenaj"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!0,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!1,contextRequired:!1,phraseOnly:!0,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-tromboliz",term:"Tromboliz",aliases:["Tromboliz","trombolitik tedavi","fibrinolitik tedavi"],category:"Tedavi yaklaşımı / damar tıkanıklığı",shortDefinition:"Fibrin pıhtısını farmakolojik olarak parçalayarak damar açıklığını yeniden sağlamayı hedefleyen tedavi yaklaşımıdır.",preAnswerSafeDefinition:"Tıkayıcı pıhtı varlığında damar açıklığını ilaçla geri kazandırmayı hedefleyen tedavi kavramıdır.",postAnswerExplanation:"İskemik inme, masif pulmoner emboli veya STEMI gibi seçilmiş durumlarda zaman penceresi, kanama riski ve kontrendikasyonlar değerlendirilerek uygulanır.",tusPearl:"Trombolizde zaman penceresi ve kanama kontrendikasyonları kritik belirleyicidir.",differentialPoint:"Trombektomi pıhtının mekanik çıkarılmasıdır; tromboliz pıhtının farmakolojik eritilmesidir.",clinicalContext:"Akut iskemik inme, pulmoner emboli ve akut koroner sendrom yönetiminde seçilmiş hastalarda gündeme gelir.",safeNestedTerms:["İskemik inme","Pulmoner emboli","STEMI","Kanama kontrendikasyonu","Trombektomi"],canonicalTerm:"Tromboliz",displayTerm:"Tromboliz",normalizedAliases:[],postAnswerExpandedExplanation:"İskemik inme, masif pulmoner emboli veya STEMI gibi seçilmiş durumlarda zaman penceresi, kanama riski ve kontrendikasyonlar değerlendirilerek uygulanır.",relatedTerms:["İskemik inme","Pulmoner emboli","STEMI","Kanama kontrendikasyonu","Trombektomi"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!1,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!0,contextRequired:!1,phraseOnly:!1,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-eklampsi",term:"Eklampsi",aliases:["Eklampsi","eclampsia"],category:"Kadın doğum / obstetrik acil",shortDefinition:"Preeklampsi zemininde gebelikte veya postpartum dönemde gelişen, başka bir nörolojik nedenle açıklanamayan jeneralize nöbettir.",preAnswerSafeDefinition:"Gebelik veya postpartum dönemde hipertansif hastalıklarla ilişkili ciddi nörolojik komplikasyonu ifade eder.",postAnswerExplanation:"Eklampside endotel disfonksiyonu ve serebral irritabilite nöbet riskini artırır; magnezyum sülfat nöbet tedavisi/profilaksisinde temel ilaçtır ve anne stabilizasyonu sonrası doğum planlanır.",tusPearl:"Preeklamptik hastada nöbet gelişirse eklampsi düşünülür; nöbet profilaksisi ve tedavisinde ilk tercih magnezyum sülfattır.",differentialPoint:"Epilepsi, intrakraniyal kanama ve metabolik nedenler ayırıcı tanıdadır; hipertansiyon/proteinüri veya organ bulguları obstetrik acil lehinedir.",clinicalContext:"Gebelikte veya postpartum dönemde hipertansiyon, baş ağrısı, görme bozukluğu ve nöbet birlikteliğinde değerlendirilir.",safeNestedTerms:["Preeklampsi","Magnezyum sülfat","HELLP sendromu","Hipertansiyon","Jeneralize nöbet"],canonicalTerm:"Eklampsi",displayTerm:"Eklampsi",normalizedAliases:[],postAnswerExpandedExplanation:"Eklampside endotel disfonksiyonu ve serebral irritabilite nöbet riskini artırır; magnezyum sülfat nöbet tedavisi/profilaksisinde temel ilaçtır ve anne stabilizasyonu sonrası doğum planlanır.",relatedTerms:["Preeklampsi","Magnezyum sülfat","HELLP sendromu","Hipertansiyon","Jeneralize nöbet"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!1,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!0,contextRequired:!1,phraseOnly:!1,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"},{id:"definition-quality-v294-akt",term:"Akt",aliases:["Akt","Protein kinase B","PKB"],category:"Sinyal iletimi / serin-treonin kinaz",shortDefinition:"PI3K yolu downstream’inde aktive olan, hücre sağkalımı, metabolizma ve büyüme sinyallerini destekleyen serin/treonin kinazdır.",preAnswerSafeDefinition:"Hücre içi sağkalım ve metabolik sinyal iletiminde görev alan protein kinazdır.",postAnswerExplanation:"PI3K tarafından üretilen PIP3, Akt’ın membrana toplanmasını ve aktivasyonunu destekler; Akt mTOR, apoptotik proteinler ve metabolik hedefler üzerinden sağkalım/büyüme yanıtı oluşturur.",tusPearl:"PTEN kaybı veya PI3K aktivasyonu Akt sinyalini artırarak antiapoptotik ve proliferatif avantaj sağlayabilir.",differentialPoint:"ERK/MAPK daha çok proliferasyon ve farklılaşma sinyaliyle; Akt ise sağkalım, metabolizma ve büyüme kontrolüyle ilişkilidir.",clinicalContext:"Kanser biyolojisi, insülin sinyali ve PI3K/Akt/mTOR yolu sorularında önemlidir.",safeNestedTerms:["PI3K","PIP3","mTOR","PTEN","Apoptoz"],canonicalTerm:"Akt",displayTerm:"Akt",normalizedAliases:[],postAnswerExpandedExplanation:"PI3K tarafından üretilen PIP3, Akt’ın membrana toplanmasını ve aktivasyonunu destekler; Akt mTOR, apoptotik proteinler ve metabolik hedefler üzerinden sağkalım/büyüme yanıtı oluşturur.",relatedTerms:["PI3K","PIP3","mTOR","PTEN","Apoptoz"],unsafeNestedTerms:[],relatedBranches:[],matchingPriority:5e3,isMultiWordTerm:!1,isGenericConcept:!1,isContextSensitive:!1,answerLeakRisk:"medium",nestedGlossaryAllowed:!0,standaloneSafe:!0,contextRequired:!1,phraseOnly:!1,sourceTextExamples:[],definitionQualityPatch:"v294-placeholder-rewrite"}];export{e as T};
